/* style.css — Saku Serambi. Palet serambi rumah: hijau daun, krem hangat, kunyit. */
:root {
  --bg: #F7F5EF;
  --surface: #FFFFFF;
  --surface-soft: #EFF3EE;
  --ink: #1C2B26;
  --muted: #55635F;
  --line: #DDE3DA;
  --green: #2E7D5B;
  --green-dark: #1E4D3B;
  --green-soft: #DCEFE4;
  --amber: #E8A33D;
  --amber-soft: #FBF0D9;
  --red: #B4452F;
  --red-soft: #F9E4DE;
  --blue: #4A7FA5;
  --purple: #8A6FBF;
  --radius: 14px;
  --shadow: 0 1px 3px rgba(28, 43, 38, .10), 0 6px 18px rgba(28, 43, 38, .06);
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 16px/1.55 -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
a { color: var(--green-dark); }
h1 { font-size: 30px; line-height: 1.2; margin: 0 0 6px; letter-spacing: -.01em; }
h2 { font-size: 20px; margin: 0 0 10px; }
h3 { font-size: 16px; margin: 0 0 8px; }
p { margin: 0 0 10px; }
.lede { color: var(--muted); font-size: 17px; max-width: 62ch; }

/* header & nav */
.topbar {
  position: sticky; top: 0; z-index: 20;
  display: flex; align-items: center; gap: 18px; flex-wrap: wrap;
  padding: 10px 22px; background: var(--green-dark); color: #fff;
  box-shadow: 0 2px 10px rgba(0, 0, 0, .18);
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: #fff; }
.brand img { border-radius: 9px; background: #fff; }
.brand-text { display: flex; flex-direction: column; line-height: 1.15; }
.brand-text strong { font-size: 19px; letter-spacing: .01em; }
.brand-text em { font-style: normal; font-size: 12px; color: #CDE6D6; }
.mainnav { display: flex; gap: 2px; flex-wrap: wrap; margin-left: auto; }
.mainnav a {
  color: #E7F2EB; text-decoration: none; font-weight: 600; font-size: 14px;
  padding: 8px 11px; border-radius: 999px;
}
.mainnav a:hover { background: rgba(255, 255, 255, .14); }
.mainnav a.active { background: #fff; color: var(--green-dark); }
.month-badge {
  margin: 0; padding: 6px 12px; border-radius: 999px;
  background: var(--amber); color: #2B1E05; font-weight: 700; font-size: 13px; white-space: nowrap;
}

main { max-width: 1120px; margin: 0 auto; padding: 26px 22px 40px; }
.view-head { margin-bottom: 18px; }
.view-head .lede { margin-bottom: 0; }

/* cards & grids */
.grid { display: grid; gap: 16px; }
.g3 { grid-template-columns: repeat(3, 1fr); }
.g2 { grid-template-columns: repeat(2, 1fr); }
.card {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 18px 20px; box-shadow: var(--shadow);
}
.card h2 { margin-bottom: 4px; }
.card .big { font-size: 30px; font-weight: 800; letter-spacing: -.01em; line-height: 1.15; }
.card .sub { color: var(--muted); font-size: 14px; }
.card .label { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.cash { border-top: 5px solid var(--green); }
.cash.amber { border-top-color: var(--amber); }
.cash.blue { border-top-color: var(--blue); }
.kpi-row { display: flex; gap: 16px; flex-wrap: wrap; margin: 4px 0 16px; }
.kpi {
  background: var(--surface); border: 1px solid var(--line); border-radius: 12px;
  padding: 12px 16px; min-width: 170px; flex: 1;
}
.kpi .k-label { font-size: 13px; color: var(--muted); font-weight: 700; }
.kpi .k-value { font-size: 22px; font-weight: 800; }
.kpi .k-note { font-size: 13px; color: var(--muted); }

/* money map */
.moneymap { display: flex; height: 20px; border-radius: 999px; overflow: hidden; margin: 12px 0 10px; }
.moneymap span { display: block; height: 20px; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chip {
  display: inline-flex; align-items: center; gap: 7px;
  background: var(--surface-soft); border: 1px solid var(--line);
  border-radius: 999px; padding: 5px 11px; font-size: 13px; font-weight: 600;
}
.chip i { width: 10px; height: 10px; border-radius: 3px; display: inline-block; }

/* bars & progress */
.bar { height: 10px; background: #E7ECE5; border-radius: 999px; overflow: hidden; }
.bar > i { display: block; height: 10px; background: var(--green); border-radius: 999px; }
.bar.thin { height: 8px; }
.bar > i.over { background: var(--red); }
.env-row { padding: 14px 0; border-top: 1px solid var(--line); }
.env-row:first-of-type { border-top: 0; }
.env-top { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.env-top b { font-size: 16px; }
.env-nums { font-size: 14px; color: var(--muted); }
.env-nums strong { color: var(--ink); }
.env-meta { display: flex; justify-content: space-between; font-size: 13px; color: var(--muted); margin-top: 6px; }
.pill {
  display: inline-block; padding: 2px 10px; border-radius: 999px;
  font-size: 12px; font-weight: 700; background: var(--green-soft); color: var(--green-dark);
}
.pill.warn { background: var(--amber-soft); color: #6B4A08; }
.pill.due { background: var(--red-soft); color: var(--red); }
.pill.done { background: var(--green-soft); color: var(--green-dark); }

/* tables */
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { text-align: left; padding: 9px 8px; border-bottom: 1px solid var(--line); vertical-align: top; }
th { font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
tr.expense td.amount { color: var(--red); }
tr.income td.amount { color: var(--green-dark); font-weight: 700; }
tr.transfer td.amount { color: var(--blue); }
.table-wrap { overflow-x: auto; }

/* forms & buttons */
form.inline { display: flex; gap: 10px; flex-wrap: wrap; align-items: end; }
.field { display: flex; flex-direction: column; gap: 4px; font-size: 13px; font-weight: 700; color: var(--muted); }
.field input, .field select {
  font: inherit; color: var(--ink); background: #fff;
  border: 1px solid #C9D2C8; border-radius: 9px; padding: 9px 11px; min-width: 0;
}
.field input:focus, .field select:focus { outline: 3px solid #BFDCC9; border-color: var(--green); }
button, .btn {
  font: inherit; font-weight: 700; cursor: pointer;
  background: var(--green); color: #fff; border: 0; border-radius: 999px; padding: 10px 18px;
}
button:hover { background: var(--green-dark); }
button.ghost { background: #fff; color: var(--green-dark); border: 1.5px solid var(--green); }
button.small { padding: 6px 13px; font-size: 13px; }
button:disabled { opacity: .5; cursor: default; }
.note { font-size: 14px; color: var(--muted); }
.result {
  margin-top: 12px; padding: 14px 16px; border-radius: 12px;
  background: var(--green-soft); border: 1px solid #BFDCC9; font-size: 15px;
}
.result b { font-size: 18px; }
.callout { background: var(--amber-soft); border: 1px solid #F0D9A8; border-radius: 12px; padding: 14px 16px; }
.callout p { margin: 0; }

/* bills & goals */
.bill-row, .goal-head { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; align-items: start; }
.bill-row { padding: 13px 0; border-top: 1px solid var(--line); }
.bill-row:first-of-type { border-top: 0; }
.bill-row .amount { font-weight: 800; font-size: 18px; white-space: nowrap; }
.goal-card .goal-nums { display: flex; justify-content: space-between; font-size: 14px; color: var(--muted); margin: 6px 0; }
.goal-card .goal-nums strong { color: var(--ink); font-size: 17px; }
.eta { font-size: 15px; font-weight: 700; color: var(--green-dark); }
.eta small { display: block; font-weight: 600; color: var(--muted); font-size: 13px; }

/* history chart (CSS bars, no JS canvas) */
.chart { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; align-items: end; margin-top: 8px; }
.chart-col { text-align: center; }
.chart-bars { display: flex; gap: 6px; justify-content: center; align-items: end; height: 150px; }
.chart-bars i { display: block; width: 34px; border-radius: 5px 5px 0 0; }
.chart-bars i.inc { background: var(--green); }
.chart-bars i.out { background: var(--amber); }
.chart-col .m { font-weight: 800; margin-top: 8px; }
.chart-col .v { font-size: 12px; color: var(--muted); line-height: 1.5; }
.legend { display: flex; gap: 16px; font-size: 13px; color: var(--muted); margin-top: 10px; }
.legend i { display: inline-block; width: 11px; height: 11px; border-radius: 3px; margin-right: 5px; }

.tip { padding: 12px 0; border-top: 1px solid var(--line); }
.tip:first-of-type { border-top: 0; }
.muted { color: var(--muted); }
.foot {
  border-top: 1px solid var(--line); padding: 22px; text-align: center;
  color: var(--muted); font-size: 14px; max-width: 1120px; margin: 0 auto 30px;
}
.foot p { margin: 0 0 6px; }
.toolbar { display: flex; gap: 10px; flex-wrap: wrap; align-items: end; margin-bottom: 14px; }
.toolbar .field { flex: 1; min-width: 160px; }
.count-line { font-size: 14px; color: var(--muted); margin-bottom: 8px; }

@media (max-width: 760px) {
  h1 { font-size: 25px; }
  .g3, .g2 { grid-template-columns: 1fr; }
  .topbar { padding: 10px 14px; gap: 10px; }
  .mainnav { margin-left: 0; order: 3; width: 100%; }
  .mainnav a { padding: 7px 9px; font-size: 13px; }
  .month-badge { margin-left: auto; }
  main { padding: 20px 14px 32px; }
  .card .big { font-size: 26px; }
  .chart-bars { height: 120px; }
  .chart-bars i { width: 24px; }
  th, td { padding: 8px 5px; }
}
